function validate([str1, str2]) {
  if (str1.length < 1 || str1.length > 10000) return 'str1 has 1 to 10^4 letters.';
  if (str1.length !== str2.length) return 'str1 and str2 must have the same length.';
  if (!/^[a-z]+$/.test(str1) || !/^[a-z]+$/.test(str2)) return 'Use lowercase English letters only.';
  return null;
}

