function canConvert(str1, str2) {
  if (str1 === str2) {
    return true;
  }

  const mapping = new Map();
  for (let i = 0; i < str1.length; i++) {
    const from = str1[i];
    const to = str2[i];
    if (mapping.has(from) && mapping.get(from) !== to) {
      return false;
    }
    mapping.set(from, to);
  }

  const targets = new Set(str2);
  return targets.size < 26;
}

