function canConvert(str1, str2) {
  // Actually perform conversions on a copy of str1 until it equals str2 or no legal move is left.
  const current = str1.split('');
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  for (let step = 0; step < 200; step++) {
    if (current.join('') === str2) return true;
    const need = new Map();
    for (let i = 0; i < current.length; i++) {
      if (need.has(current[i]) && need.get(current[i]) !== str2[i]) return false;
      need.set(current[i], str2[i]);
    }
    const present = [...need.keys()];
    // A move a -> t is legal when t is absent or t's positions need the same final letter as a's.
    const legal = (a, t) => a !== t && (!need.has(t) || need.get(t) === need.get(a));
    let move = null;
    for (const a of present) if (need.get(a) !== a && legal(a, need.get(a))) { move = [a, need.get(a)]; break; }
    if (!move) for (const a of present) for (const t of present) if (!move && legal(a, t)) move = [a, t];
    if (!move) {
      const spare = [...letters].find(t => !need.has(t));
      const a = present.find(c => need.get(c) !== c);
      if (spare === undefined || a === undefined) return false;
      move = [a, spare];
    }
    for (let i = 0; i < current.length; i++) if (current[i] === move[0]) current[i] = move[1];
  }
  return false;
}

