function generate(rand, size) {
  const large = size === 'large';
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const shuffled = () => {
    const out = alphabet.split('');
    for (let i = out.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
  };
  const mode = rand();
  if (mode < 0.35) {
    // str1 uses every letter, so the answer hinges on whether the mapping is a permutation.
    const n = large ? 4000 + Math.floor(rand() * 5000) : 26 + Math.floor(rand() * 10);
    const chars = shuffled();
    while (chars.length < n) chars.push(alphabet[Math.floor(rand() * 26)]);
    const str1 = chars.join('');
    const perm = shuffled();
    const kind = rand();
    const f = {};
    alphabet.split('').forEach((c, i) => { f[c] = kind < 0.15 ? c : kind < 0.4 ? alphabet[(i + 1) % 26] : kind < 0.7 ? perm[i] : alphabet[Math.floor(rand() * 26)]; });
    if (kind < 0.15 && rand() < 0.5) { const a = alphabet[Math.floor(rand() * 26)]; f[a] = a === 'z' ? 'a' : 'z'; }
    return [str1, str1.split('').map(c => f[c]).join('')];
  }
  const n = large ? 4000 + Math.floor(rand() * 5000) : 1 + Math.floor(rand() * 10);
  const pool = shuffled().slice(0, 1 + Math.floor(rand() * (large ? 26 : 6)));
  const str1 = Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)]).join('');
  if (mode < 0.5) {
    // Two unrelated strings over a small set of letters.
    return [str1, Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)]).join('')];
  }
  if (mode < 0.58) return [str1, str1];
  // A consistent mapping (often with chains and cycles inside the pool), sometimes broken at one spot.
  const targets = rand() < 0.5 ? pool.slice() : shuffled().slice(0, pool.length);
  const f = {};
  pool.forEach((c, i) => { f[c] = rand() < 0.6 ? targets[(i + 1) % targets.length] : targets[Math.floor(rand() * targets.length)]; });
  const out = str1.split('').map(c => f[c]);
  if (rand() < 0.25) out[Math.floor(rand() * n)] = alphabet[Math.floor(rand() * 26)];
  return [str1, out.join('')];
}
